package cn.pojuzhiyuan.captain;
import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.os.Bundle;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.InputType;
import android.view.*;
import android.text.TextUtils;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.drawable.InsetDrawable;
import android.widget.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

/** Approved field workflow: scene, team commands, assistant; two quick actions. */
public final class MainActivity extends Activity {
    private final int BLUE=0xff1769d2,INK=0xff17374b,BG=0xffeef4f8;
    private final String[] NAMES={"沙盘","本队命令","助手"};
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final ArrayList<View> controls=new ArrayList<>();private final ArrayList<JSONObject> chat=new ArrayList<>();
    private FrameLayout mapFrame;private String mapKey="";private PhotoReportDialog photoReport;
    private LinearLayout root,content;private TextView status;private String base="",token="",eventId="";private int tab=0;private boolean busy=false,destroyed=false;private JSONObject page;private SandMapView map;private AlertDialog activeDialog;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);base=getPreferences(0).getString("server","");login();}
    @Override protected void onDestroy(){destroyed=true;worker.shutdownNow();if(map!=null)map.dispose();if(photoReport!=null)photoReport.dispose();super.onDestroy();}
    private int dp(int n){return(int)(getResources().getDisplayMetrics().density*n+.5f);}
    private GradientDrawable box(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private LinearLayout vertical(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
    private TextView text(String value,int size,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(INK);t.setPadding(0,dp(5),0,dp(6));if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(16);b.setMinHeight(dp(48));b.setTextColor(Color.WHITE);b.setBackground(box(BLUE,8));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(4));b.setLayoutParams(p);b.setOnClickListener(v->{if(!busy)action.run();});controls.add(b);return b;}
    private EditText input(String hint){EditText e=new EditText(this);e.setTextSize(16);e.setHint(hint);e.setSingleLine();e.setMinHeight(dp(48));e.setAutofillHints((String[])null);controls.add(e);return e;}
    private LinearLayout card(){LinearLayout v=vertical();v.setPadding(dp(15),dp(12),dp(15),dp(12));v.setBackground(box(Color.WHITE,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(10),0,dp(3));v.setLayoutParams(p);return v;}
    private Button compact(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextSize(14);b.setAllCaps(false);b.setTextColor(INK);b.setMinHeight(dp(48));b.setMinWidth(dp(48));b.setPadding(dp(4),0,dp(4),0);b.setBackground(new InsetDrawable(box(Color.WHITE,9),dp(3)));b.setContentDescription(title);b.setOnClickListener(v->{if(!busy)action.run();});controls.add(b);return b;}
    private void shell(String subtitle,boolean tabs){
        if(map!=null&&map.getParent()!=null)((android.view.ViewGroup)map.getParent()).removeView(map);
        controls.clear();root=vertical();root.setBackgroundColor(BG);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});
        if(tabs){LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(12),0,dp(4),0);head.setBackgroundColor(Color.WHITE);LinearLayout title=vertical();TextView name=text(page.optString("event_name"),16,true);name.setPadding(0,0,0,0);name.setSingleLine();name.setEllipsize(TextUtils.TruncateAt.END);title.addView(name);StringBuilder teams=new StringBuilder();JSONArray list=page.optJSONArray("teams");if(list!=null)for(int i=0;i<list.length();i++){JSONObject t=list.optJSONObject(i);if(i>0)teams.append("、");teams.append(t.optString("name")).append(t.optBoolean("arrived")?" · 已到场":" · 未到场");}TextView sub=text(teams.toString(),12,false);sub.setPadding(0,0,0,0);sub.setSingleLine();sub.setEllipsize(TextUtils.TruncateAt.END);title.addView(sub);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button more=compact("⋯",()->{});more.setContentDescription("信息与更多操作");more.setOnClickListener(v->{if(!busy)menu(more);});head.addView(more,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(head,new LinearLayout.LayoutParams(-1,dp(56)));}
        else{LinearLayout head=vertical();head.setPadding(dp(16),dp(12),dp(16),dp(6));head.setBackgroundColor(Color.WHITE);head.addView(text("破局智援参谋",21,true));head.addView(text(subtitle,13,false));root.addView(head);}
        status=text("",13,false);status.setPadding(dp(12),dp(2),dp(12),dp(2));status.setMaxLines(2);status.setVisibility(View.GONE);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);
        if(tabs&&tab==0){mapFrame=new FrameLayout(this);root.addView(mapFrame,new LinearLayout.LayoutParams(-1,0,1));content=null;}
        else{ScrollView scroll=new ScrollView(this);content=vertical();content.setPadding(dp(12),0,dp(12),dp(12));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
        if(tabs){LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(Color.WHITE);for(int i=0;i<3;i++){final int selected=i;Button b=compact(NAMES[i],()->{tab=selected;renderSafe();refresh();});b.setTextColor(i==tab?BLUE:INK);nav.addView(b,new LinearLayout.LayoutParams(0,dp(56),1));}root.addView(nav);}setContentView(root);
    }
    private void renderSafe(){try{render(page);}catch(Exception e){message(e.getMessage());}}
    private void menu(View anchor){PopupMenu menu=new PopupMenu(this,anchor);for(String s:new String[]{"事件与地图信息","刷新资料","重试底图","我的上报记录","切换事件","退出登录"})menu.getMenu().add(s);menu.setOnMenuItemClickListener(item->{String s=item.getTitle().toString();if(s.equals("事件与地图信息"))information();else if(s.equals("刷新资料"))refresh();else if(s.equals("重试底图")){if(map!=null)map.retry();}else if(s.equals("我的上报记录"))showReports();else if(s.equals("切换事件"))selectEvent();else request("POST","/app/v2/logout",new JSONObject(),v->login());return true;});menu.show();}
    private void information(){JSONObject scene=page.optJSONObject("scene");StringBuilder details=new StringBuilder(page.optString("event_name"));JSONArray teams=page.optJSONArray("teams");if(teams!=null)for(int i=0;i<teams.length();i++){JSONObject t=teams.optJSONObject(i);details.append("\n").append(t.optString("name")).append(t.optBoolean("arrived")?" · 已到场":" · 未扫码到场");}if(scene!=null)details.append("\n\n").append(scene.optString("map_notice")).append("\n").append(scene.optString("notice")).append("\n资料时间：").append(scene.optString("updated_at"));JSONArray shortages=page.optJSONArray("shortages");if(shortages!=null&&shortages.length()>0){details.append("\n\n本队缺物回报：");for(int i=Math.max(0,shortages.length()-5);i<shortages.length();i++)details.append("\n").append(shortages.optJSONObject(i).optString("material"));}new AlertDialog.Builder(this).setTitle("破局智援参谋 · 事件信息").setMessage(details.toString()).setPositiveButton("关闭",null).show();}
    private void selectEvent(){try{JSONArray events=page.getJSONArray("events");if(events.length()<2){message("当前只有这一场可访问事件。");return;}String[] names=new String[events.length()];for(int i=0;i<names.length;i++)names[i]=events.getJSONObject(i).getString("name");new AlertDialog.Builder(this).setTitle("切换火情").setItems(names,(d,i)->{try{String next=events.getJSONObject(i).getString("id");request("GET","/app/v2/state?event_id="+URLEncoder.encode(next,"UTF-8"),null,v->{chat.clear();render(v);});}catch(Exception e){message(e.getMessage());}}).show();}catch(Exception e){message(e.getMessage());}}
    private void message(String value){status.setText(value);status.setVisibility(View.VISIBLE);if(photoReport!=null&&photoReport.isOpen()||activeDialog!=null&&activeDialog.isShowing())Toast.makeText(this,value,Toast.LENGTH_LONG).show();}
    private void loading(boolean value){busy=value;for(View v:controls)v.setEnabled(!value);if(value)message("正在连接电脑…");}
    private void login(){if(photoReport!=null){photoReport.dispose();photoReport=null;}if(map!=null){map.dispose();map=null;}mapKey="";token="";page=null;chat.clear();shell("队长安卓 App · 同网演示",false);LinearLayout c=card();c.addView(text("连接电脑并登录",22,true));c.addView(text("电脑和手机连接同一 Wi-Fi，电脑保持运行。",14,false));c.addView(text("电脑服务地址",14,true));EditText address=input("例如 192.168.1.37:18705");address.setText(base);address.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);c.addView(address);c.addView(text("队长账号",14,true));EditText account=input("手机号");account.setInputType(InputType.TYPE_CLASS_PHONE);account.setAutofillHints(View.AUTOFILL_HINT_USERNAME);c.addView(account);c.addView(text("密码",14,true));EditText password=input("账号密码");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setAutofillHints(View.AUTOFILL_HINT_PASSWORD);c.addView(password);c.addView(button("登录 App",()->{try{base=ServerAddress.normalize(address.getText().toString());request("POST","/app/v2/login",new JSONObject().put("account",account.getText().toString().trim()).put("password",password.getText().toString()),v->{password.setText("");token=v.getString("token");eventId=v.getString("event_id");getPreferences(0).edit().putString("server",base).apply();tab=0;refresh();});}catch(Exception e){message(e.getMessage());}}));content.addView(c);content.addView(text("App 只保存电脑地址，不保存密码。",14,false));}
    private interface Done{void accept(JSONObject value)throws Exception;}
    private void request(String method,String path,JSONObject value,Done done){request(method,path,value,done,()->{});}
    private void request(String method,String path,JSONObject value,Done done,Runnable onFailure){
        if(busy)return;loading(true);final String url=base+path,auth=token;worker.execute(()->{JSONObject result=null;String error=null;int code=0;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setUseCaches(false);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");if(!auth.isEmpty())c.setRequestProperty("Authorization","Bearer "+auth);if(value!=null){byte[] bytes=value.toString().getBytes(StandardCharsets.UTF_8);c.setDoOutput(true);c.setFixedLengthStreamingMode(bytes.length);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream out=c.getOutputStream()){out.write(bytes);}}code=c.getResponseCode();String type=c.getContentType();if(type==null||!type.startsWith("application/json"))throw new IOException("请核对电脑地址和当前App服务版本。");InputStream in=code>=400?c.getErrorStream():c.getInputStream();if(in==null)throw new IOException("电脑没有返回有效数据。");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream source=in){byte[] bytes=new byte[4096];int n;while((n=source.read(bytes))!=-1){if(out.size()+n>2*1024*1024)throw new IOException("返回内容过大。");out.write(bytes,0,n);}}result=new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));if(code!=200||!result.optBoolean("ok"))error=result.optString("message","未完成，请刷新核对。");}catch(Exception e){error="连接或提交未确认。请保留输入，检查同一 Wi-Fi 和电脑服务；刷新核对后再决定是否重试。\n"+e.getMessage();}finally{if(c!=null)c.disconnect();}final JSONObject data=result;final String failure=error;final int response=code;runOnUiThread(()->{if(destroyed)return;loading(false);if(failure!=null){onFailure.run();if((response==401||(response==403&&failure.contains("登录已失效")))&&(photoReport==null||!photoReport.isOpen())){if(activeDialog!=null)activeDialog.dismiss();activeDialog=null;login();}message(failure);return;}status.setVisibility(View.GONE);try{done.accept(data);}catch(Exception e){message("数据待核对："+e.getMessage());}});});
    }
    private String eventQuery(){try{return "?event_id="+URLEncoder.encode(eventId,"UTF-8");}catch(Exception e){return "";}}
    private void refresh(){request("GET","/app/v2/state"+eventQuery(),null,this::render);}
    private void render(JSONObject value)throws Exception{page=value;eventId=value.getString("event_id");shell("队长现场端",true);if(tab==0)renderScene(value);else if(tab==1)renderCommands(value);else renderAssistant();}
    private void renderScene(JSONObject value)throws Exception{
        JSONObject scene=value.getJSONObject("scene");String key=base+"|"+token+"|"+eventId;
        if(map==null||!key.equals(mapKey)){if(map!=null)map.dispose();map=new SandMapView(this,base,token,eventId,scene);mapKey=key;}else map.update(scene);
        mapFrame.addView(map,new FrameLayout.LayoutParams(-1,-1));
        LinearLayout quick=new LinearLayout(this);quick.addView(compact("扫码到场",()->startActivityForResult(new Intent(this,ScanActivity.class),81)),new LinearLayout.LayoutParams(dp(96),dp(48)));quick.addView(compact("信息上报",this::report),new LinearLayout.LayoutParams(dp(96),dp(48)));quick.addView(compact("物资缺乏",this::shortage),new LinearLayout.LayoutParams(dp(96),dp(48)));FrameLayout.LayoutParams qp=new FrameLayout.LayoutParams(-2,dp(48),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);qp.bottomMargin=dp(12);mapFrame.addView(quick,qp);
        LinearLayout zoom=vertical();zoom.addView(compact("＋",()->map.zoom(1)),new LinearLayout.LayoutParams(dp(48),dp(48)));zoom.addView(compact("－",()->map.zoom(-1)),new LinearLayout.LayoutParams(dp(48),dp(48)));FrameLayout.LayoutParams zp=new FrameLayout.LayoutParams(dp(48),-2,Gravity.TOP|Gravity.RIGHT);zp.topMargin=dp(32);zp.rightMargin=dp(8);mapFrame.addView(zoom,zp);
    }
    private void report(){chooseTeam(team->{photoReport=new PhotoReportDialog(this,team,(value,done)->request("POST","/app/v2/report"+eventQuery(),value,r->{done.finish(true);photoReport=null;refresh();},()->done.finish(false)));photoReport.show();});}
    private void showReports(){request("GET","/app/v2/reports"+eventQuery(),null,v->{JSONArray rows=v.getJSONArray("reports");LinearLayout box=vertical();box.setPadding(dp(16),0,dp(16),dp(12));if(rows.length()==0)box.addView(text("暂无本队信息上报",16,false));for(int i=rows.length()-1;i>=0;i--){JSONObject row=rows.getJSONObject(i);box.addView(text(row.getString("content"),16,true));box.addView(text(row.getString("time")+" · 待核实",13,false));JSONArray photos=row.getJSONArray("photos");for(int j=0;j<photos.length();j++){final int index=j;box.addView(button("查看照片 "+(j+1),()->viewPhoto(row,index)));}}ScrollView scroll=new ScrollView(this);scroll.addView(box);new AlertDialog.Builder(this).setTitle("我的上报记录").setView(scroll).setPositiveButton("关闭",null).show();});}
    private void viewPhoto(JSONObject row,int index){String url;try{url=base+"/app/v2/report-photo?event_id="+URLEncoder.encode(eventId,"UTF-8")+"&report_id="+URLEncoder.encode(row.getString("id"),"UTF-8")+"&index="+index;}catch(Exception e){message(e.getMessage());return;}message("正在读取照片…");final String auth=token;worker.execute(()->{byte[] bytes=null;String error=null;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestProperty("Authorization","Bearer "+auth);if(c.getResponseCode()!=200||!"image/jpeg".equals(c.getContentType()))throw new IOException("照片暂不可读取，请刷新核对");try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>1024*1024)throw new IOException("照片过大");out.write(buffer,0,n);}bytes=out.toByteArray();}}catch(Exception e){error=e.getMessage();}finally{if(c!=null)c.disconnect();}final byte[] ready=bytes;final String failure=error;runOnUiThread(()->{if(destroyed)return;if(failure!=null){message(failure);return;}Bitmap bitmap=BitmapFactory.decodeByteArray(ready,0,ready.length);if(bitmap==null){message("照片格式不可读");return;}status.setVisibility(View.GONE);ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);new AlertDialog.Builder(this).setTitle("队伍上报照片 · 待核实").setView(image).setPositiveButton("关闭",null).setOnDismissListener(d->bitmap.recycle()).show();});});}
    private void renderCommands(JSONObject value)throws Exception{
        JSONArray commands=value.getJSONArray("commands");if(commands.length()==0){LinearLayout empty=card();empty.addView(text("暂无本队命令",19,true));empty.addView(text("上级向本队下达命令后，在这里查看并提交完成回复。",15,false));content.addView(empty);}
        for(int i=0;i<commands.length();i++){JSONObject command=commands.getJSONObject(i);LinearLayout c=card();c.addView(text(command.getString("title"),19,true));c.addView(text("执行队伍："+command.getString("team_name"),14,true));c.addView(text(command.getString("content"),16,false));if(!command.optString("location").isEmpty())c.addView(text("任务位置："+command.optString("location"),14,false));c.addView(text("时间要求："+command.optString("time_requirement"),14,false));if(!command.optString("completion_standard").isEmpty())c.addView(text("完成要求："+command.optString("completion_standard"),14,false));c.addView(text(command.optString("status"),14,true));JSONArray replies=command.getJSONArray("replies");for(int j=0;j<replies.length();j++){JSONObject r=replies.getJSONObject(j);c.addView(text("本队完成回复："+r.getString("reply")+"\n"+r.getString("time"),14,false));}if(command.optBoolean("can_reply"))c.addView(button("提交完成回复",()->reply(command)));content.addView(c);}
    }
    private interface TeamDone{void accept(String id)throws Exception;}
    private void chooseTeam(TeamDone done){try{JSONArray teams=page.getJSONArray("teams");if(teams.length()==0){message("当前事件没有本人负责的队伍。");return;}if(teams.length()==1){done.accept(teams.getJSONObject(0).getString("id"));return;}String[] names=new String[teams.length()];for(int i=0;i<names.length;i++)names[i]=teams.getJSONObject(i).getString("name");new AlertDialog.Builder(this).setTitle("选择本人负责的队伍").setItems(names,(d,index)->{try{done.accept(teams.getJSONObject(index).getString("id"));}catch(Exception e){message(e.getMessage());}}).show();}catch(Exception e){message(e.getMessage());}}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(photoReport!=null&&photoReport.result(requestCode,resultCode,data))return;if(requestCode==81&&resultCode==RESULT_OK&&data!=null){try{String qr=QrPayload.parse(data.getStringExtra("qr"),base,eventId);chooseTeam(team->{new AlertDialog.Builder(this).setTitle("确认本队到场").setMessage("本次按整队满编计入到场，不再填写人员或人数。").setNegativeButton("取消",null).setPositiveButton("确认到场",(d,w)->{try{request("POST","/app/v2/arrival"+eventQuery(),new JSONObject().put("team_id",team).put("qr_id",qr).put("request_id",UUID.randomUUID().toString()),v->{tab=0;refresh();});}catch(Exception e){message(e.getMessage());}}).show();});}catch(Exception e){message(e.getMessage());}}}
    private interface SubmitText{void accept(String value,String requestId,AlertDialog dialog)throws Exception;}
    private void textDialog(String title,String hint,boolean multiline,SubmitText submit){LinearLayout box=vertical();box.setPadding(dp(20),dp(8),dp(20),dp(4));EditText input=input(hint);if(multiline){input.setSingleLine(false);input.setMinLines(3);}box.addView(input);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(box).setNegativeButton("取消",null).setPositiveButton("提交",null).create();String id=UUID.randomUUID().toString();dialog.setOnDismissListener(d->{if(activeDialog==dialog)activeDialog=null;});dialog.setOnShowListener(d->{Button send=dialog.getButton(AlertDialog.BUTTON_POSITIVE);controls.add(send);send.setOnClickListener(v->{if(busy)return;String s=input.getText().toString().trim();if(s.isEmpty()){input.setError("请填写"+hint);return;}try{submit.accept(s,id,dialog);}catch(Exception e){message(e.getMessage());}});});activeDialog=dialog;dialog.show();}
    private void shortage(){chooseTeam(team->textDialog("物资缺乏回报","缺少的物资名称",false,(name,id,dialog)->request("POST","/app/v2/shortage"+eventQuery(),new JSONObject().put("team_id",team).put("material",name).put("request_id",id),v->{dialog.dismiss();tab=0;refresh();})));}
    private void reply(JSONObject command){textDialog("本队完成回复","本队命令完成情况",true,(reply,id,dialog)->request("POST","/app/v2/reply"+eventQuery(),new JSONObject().put("command_id",command.getString("id")).put("version_ref",command.getString("version_ref")).put("reply",reply).put("request_id",id),v->{dialog.dismiss();refresh();}));}
    private void renderAssistant(){LinearLayout c=card();c.addView(text("查询场内信息",20,true));c.addView(text("可问火情、气象、队伍、本队命令、物资和风险点。",14,false));EditText question=input("输入想了解的现场信息");question.setSingleLine(false);question.setMinLines(2);c.addView(question);c.addView(button("查询",()->{try{String q=question.getText().toString().trim();if(q.isEmpty()){question.setError("请输入问题");return;}request("POST","/app/v2/ask"+eventQuery(),new JSONObject().put("question",q),v->{v.put("question",q);chat.add(v);render(page);});}catch(Exception e){message(e.getMessage());}}));content.addView(c);for(int i=chat.size()-1;i>=0;i--){JSONObject v=chat.get(i);LinearLayout answer=card();answer.addView(text(v.optString("question"),17,true));answer.addView(text(v.optString("answer"),16,false));JSONArray sources=v.optJSONArray("sources");answer.addView(text("资料时间："+v.optString("updated_at","未登记")+"\n来源："+(sources==null||sources.length()==0?"暂无匹配资料":sources.toString())+"\n"+v.optString("notice"),13,false));content.addView(answer);}}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(photoReport!=null)photoReport.permission(code,grants);}
    @Override public void onBackPressed(){if(!token.isEmpty())moveTaskToBack(true);else super.onBackPressed();}
}
